$simdProof=Track-File (Join-Path $root 'build/khc-causal-simd-quotient-20261002-warning-fix/report.json') 'simd-codec-proof'
if($simdProof.before_sha256 -cne '09A9497FC34C580E7D18EFF3F0BCB988439FF40B6221BE77074C354B8D19BE7E'){throw 'SIMD codec proof SHA'}
$simdJson=Get-Content -LiteralPath $simdProof.path -Raw|ConvertFrom-Json
if($simdJson.status -cne 'correctness_and_size_passed_not_timed' -or $simdJson.failure -or $simdJson.timing_used -or $simdJson.checks.Count -ne 47 -or $simdJson.invocations.Count -ne 83 -or $simdJson.identities.Count -ne 263 -or $simdJson.owned_tmp_or_reparse -ne 0 -or $simdJson.owned_pdb -ne 0 -or $simdJson.frame_bytes -ne 483496){throw 'SIMD codec proof incomplete'}
if(($simdJson.variants -join ',') -cne 'native,checked,scalar,scalar-checked'){throw 'SIMD codec variant matrix'}
$simdOrdinary=@($simdJson.identities|Where-Object {$_.role -ceq 'native-codec' -and $_.path -ceq $candidate.path -and $_.before_sha256 -ceq $candidate.before_sha256 -and $_.bytes -eq 247296})
if($simdOrdinary.Count -ne 1){throw 'Candidate not the SIMD ordinary codec'}
$simdRefusals=@($simdJson.invocations|Where-Object exit -ne 0)
if($simdRefusals.Count -ne 8 -or @($simdRefusals|Where-Object {$_.exit -ne 1 -or !$_.stderr -or $_.stdout}).Count -or @($simdJson.invocations|Where-Object {$_.exit -eq 0 -and $_.stderr}).Count){throw 'SIMD codec invocation mismatch'}
$simdNumericProof=Track-File (Join-Path $root 'build/khc-simd-quotient-20261002/report.json') 'simd-numeric-proof'
if($simdNumericProof.before_sha256 -cne 'FE390BBE820107F32570BFC6E416E5FA947743848131F8EB8513BFC4E02E1EDE'){throw 'SIMD numeric proof SHA'}
$simdNumericJson=Get-Content -LiteralPath $simdNumericProof.path -Raw|ConvertFrom-Json
if($simdNumericJson.status -cne 'batch_numeric_verified_not_codec_or_timing' -or $simdNumericJson.failure -or $simdNumericJson.timing_used -or $simdNumericJson.checks.Count -ne 32 -or $simdNumericJson.invocations.Count -ne 87 -or $simdNumericJson.identities.Count -ne 10 -or $simdNumericJson.owned_tmp_or_reparse -ne 0 -or !$simdNumericJson.features.avx2_available -or $simdNumericJson.summaries.Count -ne 4){throw 'SIMD numeric proof incomplete'}
foreach($call in $simdNumericJson.invocations){
    $expectedExit=if($call.argv.Count -eq 0 -or ($call.argv.Count -gt 2 -and $call.argv[0] -ceq 'query' -and $call.argv[2] -ceq '-1')){2}else{0}
    if($call.exit -ne $expectedExit -or ($expectedExit -eq 0 -and $call.stderr) -or ($expectedExit -ne 0 -and (!$call.stderr -or $call.stdout))){throw 'SIMD numeric invocation failure'}
}
$matrix=@($simdNumericJson.summaries|ForEach-Object {"$($_.opt)/$($_.backend)"}|Sort-Object)
if(($matrix -join ',') -cne '2/avx2,2/scalar,3/avx2,3/scalar'){throw 'SIMD numeric matrix'}
foreach($summary in $simdNumericJson.summaries){
    $counts=$summary.summary
    if($counts.records -ne 9293629 -or $counts.matched -ne 9293629 -or $counts.batches -ne 2323408 -or $counts.certificate_fallback -ne 0 -or $counts.fingerprint_u64 -cne 'e5c97b90b4768836'){throw 'SIMD numeric coverage mismatch'}
    if(($counts|ConvertTo-Json -Compress) -cne ($simdNumericJson.summaries[0].summary|ConvertTo-Json -Compress)){throw 'SIMD numeric summary mismatch'}
}
$report['simd_proofs']=[ordered]@{codec=$simdProof;numeric=$simdNumericProof}

$report['historical_budget_guard_repairs']=
